export function saveArmyTemplate(s,a){warInit(s);if(!a)return 'Нет армии';s.states[a.f].templates.push({name:'Состав '+(s.states[a.f].templates.length+1),units:a.units.map(q=>Math.ceil(q/60))});return 'Шаблон сохранён';}
