 for(let f=1;f<s.cities.length;f++){const prev=cells[f-1],candidates=[];for(let i=0;i<N;i++)if(s.map.land[i]&&s.map.fert[i]>.35&&dist(i,prev)>=range-3&&dist(i,prev)<=range+3&&cells.every(j=>dist(i,j)>7))candidates.push(i);candidates.sort((a,b)=>Math.abs(dist(a,prev)-range)-Math.abs(dist(b,prev)-range)||b-a);const next=candidates.slice(0,120).find(i=>pathfind(s,prev,i,-1).length);if(next==null)break;cells.push(next);}
