export function step(s,trace=null){if(s.battle)return;economicInit(s);const before=materialTotals(s),src=s.ledger.source.slice(),sink=s.ledger.sink.slice(),ms=s.ledger.moneySink,mp=s.ledger.moneySource;s.day++;navalStep(s);transportStep(s);if(s.day%4===0)economy(s);if(s.day%20===0){recalcTerritory(s);ai(s)}warfare(s);fiscalStep(s);const after=materialTotals(s);for(let k=0;k<17;k++)s.ledger.maxGoodsError=Math.max(s.ledger.maxGoodsError,Math.abs(after.goods[k]-before.goods[k]-(s.ledger.source[k]-src[k])+(s.ledger.sink[k]-sink[k])));s.ledger.maxMoneyError=Math.max(s.ledger.maxMoneyError,Math.abs(after.money-before.money+(s.ledger.moneySink-ms)-(s.ledger.moneySource-mp)));if(trace&&s.day%(trace.interval||20)===0)trace.checkpoints.push({day:s.day,hash:simulationHash(s)});}
export function economicSnapshot(s){economicInit(s);const totals=materialTotals(s);return {day:s.day,population:s.fleets.reduce((n,v)=>n+v.crew,0)+s.cities.reduce((n,c)=>n+c.pop+c.returning,0)+s.armies.reduce((n,a)=>n+strength(a),0)+s.hospitals.reduce((n,p)=>n+p.n,0)+s.prisoners.reduce((n,p)=>n+p.n,0),cities:s.cities.length,wealth:s.cities.reduce((n,c)=>n+c.wealth,0)/Math.max(1,s.cities.length),trade:s.shipments.reduce((n,sh)=>n+sh.goods.reduce((a,b)=>a+b,0),0),prices:GOODS.map((_,k)=>s.cities.reduce((n,c)=>n+c.market[k],0)/Math.max(1,s.cities.length)),production:GOODS.map((_,k)=>s.cities.reduce((n,c)=>n+c.output[k],0)),stocks:totals.goods,money:totals.money,states:s.states.map(st=>({id:st.id,gold:st.gold,bankruptcies:st.bankruptcies,insolventDays:st.insolventDays,cashEvents:st.cashEvents,structuralDays:st.structuralDays,crisisEpisodes:st.crisisEpisodes,totalStructuralDays:st.totalStructuralDays,totalCrisisDays:st.totalCrisisDays,budget:{...st.budget},strategy:st.strategy,army:s.armies.filter(a=>a.f===st.id).reduce((n,a)=>n+strength(a),0),cities:s.cities.filter(c=>c.f===st.id).length})),roles:s.cities.map(c=>({name:c.name,role:c.economicRole,build:c.build.slice(),tradeIn:c.tradeIn.slice(),tradeOut:c.tradeOut.slice(),output:c.output.slice(),foodRatio:c.lastFoodRatio,shortageDays:c.shortageDays,crisisDays:c.crisisDays})),ledger:{...s.ledger,source:[...s.ledger.source],sink:[...s.ledger.sink]}};}
